import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Performance Meeting 2022-10-13","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-10-13","date":"2022-10-13T00:00:00.000Z","updated":"2022-10-21T00:00:00.000Z","tags":["Ceph性能测试","CBT工具","存储后端比较","Seagate Motor","Deos"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-10-13.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-10-13.md","lastUpdated":1780460162000}'),l={name:"posts/2022/Ceph_Performance_Meeting_2022-10-13.md"};function i(s,e,n,h,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<p>Ceph性能会议2022年10月13日的纪要如下：</p><h3 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h3><p>本次会议主要讨论了使用CBT（Ceph Benchmarking Tool）进行不同存储后端（如Motor和Deos）的性能测试。</p><h3 id="讨论内容" tabindex="-1">讨论内容 <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容&quot;">​</a></h3><ol><li><strong>CBT的使用</strong>： 讨论了使用CBT进行性能测试的必要性，并计划将其应用于Motor和Deos等不同存储后端。</li><li><strong>Motor和Deos的状态</strong>： 分析了Motor和Deos的开源项目和硬件需求，Motor由Seagate开发，Deos由Intel开发。</li><li><strong>CBT的扩展</strong>： 讨论了如何扩展CBT，使其能够支持更多存储后端，如Deos，并增加客户端端点的功能。</li><li><strong>性能和功能实现</strong>： 讨论了Deos的性能，特别是在未启用复制模式下的高速表现，以及其他功能如多部分上传的实现情况。</li><li><strong>合作与联系</strong>： 建议与Seagate合作，共同推进CBT的发展，并确定了与Seagate团队的联系人Gregory Taretsky。</li><li><strong>后续行动计划</strong>： Mark计划首先尝试安装和运行这些存储系统，并记录部署过程，然后逐步自动化这些过程，并探索如何将这些系统集成到CBT中。</li></ol><h3 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h3><ul><li>确定与Seagate的合作，特别是关于Motor和Deos的集成。</li><li>Mark将负责初步的安装和测试工作，并与Seagate团队联系。</li></ul><h3 id="后续行动" tabindex="-1">后续行动 <a class="header-anchor" href="#后续行动" aria-label="Permalink to &quot;后续行动&quot;">​</a></h3><ul><li>Mark将联系Gregory Taretsky，获取更多关于Motor和Deos的信息。</li><li>继续改进CBT，使其支持更多的存储后端和性能测试。</li><li>讨论RBD的性能改进，特别是与Seagate的合作和CBT的扩展。</li></ul><h3 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h3><ul><li>讨论了Deos的高性能表现和潜在的应用场景。</li></ul><h3 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h3><p>会议在讨论了所有议题后结束，感谢所有参与者的贡献。</p><p>本次会议旨在通过CBT工具比较和测试Ceph生态系统中不同存储后端的性能，并与Seagate合作以优化这些存储系统的性能。</p>',14)])])}const g=a(l,[["render",i]]);export{_ as __pageData,g as default};
